class A:
 def __hash__(self): raise ValueError("wrong")
 def use(self): return 7
a=A()
print(hash(a.use)==(object.__hash__(a)^hash(A.use)))

class A:
 def use(self): return 7
a=A()
b=A()
d={a.use:7,b.use:8}
print(len(d),d[a.use],d[b.use])

class A:
 def first(self): pass
 def second(self): pass
a=A()
d={a.first:7,a.second:8}
print(len(d),d[a.first],d[a.second])

class A:
 @classmethod
 def use(cls): pass
class B(A): pass
print(A.use==A().use,hash(A.use)==hash(A().use),A.use==B.use)
print({A.use:7,B.use:8}[A.use])

class A:
 @staticmethod
 def use(): pass
print(A.use is A().use,hash(A.use)==hash(A().use),{A.use:7}[A().use])

class A:
 def use(self): pass
class B(A):
 def get(self): return super().use
b=B()
print(b.use==b.get(),hash(b.use)==hash(b.get()),{b.use:7}[b.get()])

class A:
 def use(self): return 7
f=A().use
d={f:[7]}
print(d[f][0],f())

class A:
 def use(self): pass
hash(object=A().use)

class A:
 def use(self): pass
hash(A().use,7)

class A:
 def __index__(self): raise ValueError("wrong")
 def __hash__(self):
  print("hash")
  return 7
a=A()
print(hash(slice(a))==hash(slice(a)))

class A:
 def __init__(self,n): self.n=n
 def __hash__(self):
  print(self.n)
  return self.n
hash(slice(A(1),A(2),A(3)))

class A:
 def __hash__(self):
  print("wrong")
  return 7
hash(slice([],A(),A()))

class A:
 def __hash__(self):
  print("entered")
  raise ValueError("bad")
hash(slice(A()))

class A:
 def __hash__(self): return "bad"
hash(slice(A()))

class D:
 def __get__(self,obj,owner):
  print("bind")
  return lambda: 7
class A:
 __hash__=D()
a=A()
print(hash(slice(a))==hash(slice(a)))

class D:
 def __get__(self,obj,owner):
  print("bind")
  raise ValueError("bad")
class A:
 __hash__=D()
hash(slice(A()))

class A:
 def __hash__(self): return True
print(hash(slice(A()))==hash(slice(1)))

class A:
 def __hash__(self): return -1
print(hash(slice(A()))==hash(slice(-2)))

class A:
 __hash__=None
hash(slice(A()))

class A:
 def __hash__(self): raise ValueError("bad")
hash((A(),))
